import BaseDrawing from './BaseDrawing';
// import Fire from './Fire'
export default class Rocket extends BaseDrawing {
    // _fires: Fire[] = []
    constructor({ pos, length, width, exhausts, rotation = 0, image, color, }, p5) {
        super({ pos, rotation }, p5);
        this._isTurningLeft = false;
        this.length = length;
        this.width = width;
        this.exhausts = exhausts;
        this.image = image;
        this.color = color;
        this.updatePoints();
    }
    updatePoints() {
        const p = this._p5;
        this._tipPoint = p.createVector(0, -this.length * 0.7);
        this._rearCenterPoint = p.createVector(0, this.length * 0.3);
        this._rearPoints = [
            p.createVector(-this.width / 2, this.length * 0.35),
            p.createVector(this.width / 2, this.length * 0.35),
        ];
        this._leftCurvePoints = [
            this._rearPoints[0].copy().add(0, -this.length * 0.3),
            this._tipPoint.copy().add(-this.width / 4, this.length * 0.05),
        ];
        this._rightCurvePoints = [
            this._rearPoints[1].copy().add(0, -this.length * 0.3),
            this._tipPoint.copy().add(this.width / 4, this.length * 0.05),
        ];
        switch (this.exhausts) {
            case 1:
                this._exhaustPoints = [this._rearCenterPoint.copy().add(0, this.length * 0.05)];
                this._exhaustWidth = this.width * 0.3;
                break;
            case 2:
                this._exhaustPoints = [
                    this._rearCenterPoint.copy().add(-this.width / 5, this.length * 0.07),
                    this._rearCenterPoint.copy().add(this.width / 5, this.length * 0.07),
                ];
                this._exhaustWidth = this.width * 0.13;
                break;
            case 3:
                this._exhaustPoints = [
                    this._rearCenterPoint.copy().add(-this.width * 0.3, this.length * 0.1),
                    this._rearCenterPoint.copy().add(0, this.length * 0.05),
                    this._rearCenterPoint.copy().add(this.width * 0.3, this.length * 0.1),
                ];
                this._exhaustWidth = this.width * 0.08;
                break;
        }
    }
    wobble() {
        // if (this.rotation >= 60) {
        // 	this._isTurningLeft = false
        // } else if (this.rotation <= 30) {
        // 	this._isTurningLeft = true
        // }
        this.rotation += window.fxrand() - 0.5;
        this.rotation = Math.min(Math.max(this.rotation, 30), 60);
    }
    drawGuidingLines() {
        this.isolate(() => {
            const p = this._p5;
            p.fill('#0F0');
            p.circle(this._tipPoint.x, this._tipPoint.y, 10);
            p.circle(this._rearCenterPoint.x, this._rearCenterPoint.y, 10);
            p.circle(this._rearPoints[0].x, this._rearPoints[0].y, 10);
            p.circle(this._rearPoints[1].x, this._rearPoints[1].y, 10);
            p.circle(0, 0, 10);
            p.fill('#0FF');
            p.circle(this._leftCurvePoints[0].x, this._leftCurvePoints[0].y, 10);
            p.circle(this._leftCurvePoints[1].x, this._leftCurvePoints[1].y, 10);
            p.circle(this._rightCurvePoints[0].x, this._rightCurvePoints[0].y, 10);
            p.circle(this._rightCurvePoints[1].x, this._rightCurvePoints[1].y, 10);
            // p.line(this._rearPoints[0].x, this._rearPoints[0].y, this._tipPoint.x, this._tipPoint.y)
            // p.line(this._rearPoints[1].x, this._rearPoints[1].y, this._tipPoint.x, this._tipPoint.y)
            // p.line(
            // 	this._rearPoints[0].x,
            // 	this._rearPoints[0].y,
            // 	this._rearCenterPoint.x,
            // 	this._rearCenterPoint.y
            // )
            // p.line(
            // 	this._rearPoints[1].x,
            // 	this._rearPoints[1].y,
            // 	this._rearCenterPoint.x,
            // 	this._rearCenterPoint.y
            // )
        });
    }
    drawExhaust() {
        this.isolate(() => {
            const p = this._p5;
            p.fill('#2C272E');
            p.stroke('#2C272E');
            p.strokeJoin(p.ROUND);
            p.strokeWeight(10);
            p.rectMode(p.RADIUS);
            this._exhaustPoints.forEach(({ x, y }) => {
                p.rect(x, y - this.length * 0.1, this._exhaustWidth, this.length * 0.15);
            });
        });
    }
    drawWindow() {
        const p = this._p5;
        const radius = Math.min(this.width, this.length * 2) * 0.3;
        const windowWidth = Math.min(this.width, this.length * 2) / 30;
        this.isolate(() => {
            p.fill('#71DFE7');
            p.circle(0, -this.length * 0.35, radius);
        });
        this.isolate(() => {
            p.noFill();
            p.stroke('#2C272E');
            p.strokeWeight(windowWidth);
            p.circle(0, -this.length * 0.35, radius);
        });
    }
    draw() {
        this.isolate(() => {
            const p = this._p5;
            /** Prepare Canvas */
            p.stroke(this.color);
            p.fill(this.color);
            p.angleMode(p.DEGREES);
            p.translate(this.pos.x, this.pos.y);
            p.rotate(this.rotation);
            /** --------------- */
            this.drawExhaust();
            this.wobble();
            this.isolate(() => {
                p.beginShape();
                p.vertex(this._rearPoints[0].x, this._rearPoints[0].y);
                p.strokeJoin(p.ROUND);
                p.strokeWeight(10);
                p.bezierVertex(this._leftCurvePoints[0].x, this._leftCurvePoints[0].y, this._leftCurvePoints[1].x, this._leftCurvePoints[1].y, this._tipPoint.x, this._tipPoint.y);
                p.bezierVertex(this._rightCurvePoints[1].x, this._rightCurvePoints[1].y, this._rightCurvePoints[0].x, this._rightCurvePoints[0].y, this._rearPoints[1].x, this._rearPoints[1].y);
                // rear
                p.bezierVertex(this._rearCenterPoint.x, this._rearCenterPoint.y, this._rearCenterPoint.x, this._rearCenterPoint.y, this._rearPoints[0].x, this._rearPoints[0].y);
                p.endShape();
            });
            if (this.image) {
                this.isolate(() => {
                    const imageSize = Math.min(this.width, this.length) * 0.3;
                    // p.stroke('#0F61FF')
                    // p.strokeWeight(2)
                    p.fill('#FFF');
                    p.circle(0, 0, imageSize * 1.2);
                    // p.rotate(-90)
                    p.image(this.image, -imageSize / 2, -imageSize / 2, imageSize, imageSize);
                    this.image.loadPixels();
                });
            }
            this.drawWindow();
            // this.drawGuidingLines()
        });
    }
}
