import BaseDrawing from './BaseDrawing';
export default class Fire extends BaseDrawing {
    constructor({ pos, radius, rotation = 0, speed = 10, colorPalette, }, p5) {
        super({ pos, rotation }, p5);
        this.currPos = this._p5.createVector(0, 0);
        this.speed = 10;
        this.radius = radius;
        this.speed = speed;
        this._xVariation = radius / 5;
        this._radiusSub = radius / 50 + speed / 70;
        this.colorPalette = colorPalette;
        // pick a random color
        this.color = p5.color(255);
        const r = window.fxrand() * 3;
        if (r < 1) {
            this.color = this.colorPalette[0];
        }
        else if (r >= 1 && r < 2) {
            this.color = this.colorPalette[1];
        }
        else if (r >= 2) {
            this.color = this.colorPalette[2];
        }
    }
    draw() {
        const p = this._p5;
        this.isolate(() => {
            p.noStroke();
            p.fill(this.color);
            p.angleMode(p.DEGREES);
            p.translate(this.pos.x, this.pos.y);
            p.rotate(this.rotation);
            // p.scale(0.5)
            // p.ellipse(0, 0, this.radius)
            p.ellipse(this.currPos.x, this.currPos.y, this.radius);
        });
    }
    update() {
        this.currPos.add(window.fxrand() * this._xVariation - this._xVariation / 2, window.fxrand() * this.speed + this.speed / 2);
        if (this.radius >= 0)
            this.radius -= this._radiusSub;
    }
}
