import BaseDrawing from './BaseDrawing';
export default class Background extends BaseDrawing {
    constructor({ rotation = 0, speed = 10 }, p5) {
        super({ pos: p5.createVector(p5.width / 2, p5.height / 2), rotation }, p5);
        this.currPos = this._p5.createVector(0, 0);
        this.distance = 0;
        this.speed = speed;
        this.stars = Array.from({ length: p5.height })
            .fill('')
            .map(() => {
            return p5.createVector(window.fxrand() * p5.width - p5.width / 2, window.fxrand() * p5.height - p5.height / 2);
        });
    }
    draw() {
        const p = this._p5;
        this.isolate(() => {
            p.noStroke();
            p.fill('#FFF');
            p.angleMode(p.DEGREES);
            p.translate(this.pos.x, this.pos.y);
            p.rotate(this.rotation);
            p.translate(0, this.distance);
            this.stars.forEach((pos) => {
                p.circle(pos.x, pos.y, 2);
            });
            // p.ellipse(0, 0, this.radius)
            // p.ellipse(this.currPos.x, this.currPos.y, this.radius)
        });
    }
    update() {
        this.distance += this.speed;
        if (this.distance >= this._p5.height)
            this.distance = 0;
    }
}
