import P5 from 'p5';
import Background from './Background';
import Fire from './Fire';
import Rocket from './Rocket';
import features from './features';
const sketch = function (p) {
    let rocket;
    let background;
    let bgCanvas;
    const fires = [];
    let scale = 1;
    let firePalette;
    const rotation = 45;
    p.setup = function () {
        p.createCanvas(p.windowWidth, p.windowHeight);
        scale = Math.min(p.width, p.height) / 1000;
        const bgCanvasSize = Math.max(p.width, p.height);
        bgCanvas = p.createGraphics(bgCanvasSize, bgCanvasSize);
        bgCanvas.clear();
        firePalette = [
            p.color(features.firePalette.value[0]),
            p.color(features.firePalette.value[1]),
            p.color(features.firePalette.value[2]),
        ];
        p.frameRate(60);
        rocket = new Rocket({
            pos: p.createVector(p.width / 2, p.height / 2),
            width: features.width * scale,
            length: features.length * scale,
            exhausts: features.exhausts.value,
            rotation,
            color: p.color(features.bodyColor.value),
        }, p);
        background = new Background({ rotation: 0, speed: (features.speed / 15) * scale }, bgCanvas);
        background.draw();
        const fireRadius = rocket.exhausts === 1
            ? rocket._exhaustWidth * 2
            : rocket.exhausts === 2
                ? rocket._exhaustWidth * 2.5
                : rocket._exhaustWidth * 3;
        for (let i = 0; i < 60; i++) {
            rocket._exhaustPoints.forEach(({ x, y }) => {
                fires.push(new Fire({
                    pos: p
                        .createVector(x, y + rocket._exhaustWidth / 2)
                        .rotate(rocket.rotation)
                        .add(rocket.pos),
                    radius: fireRadius,
                    rotation: rocket.rotation,
                    speed: features.speed * scale,
                    colorPalette: firePalette,
                }, p));
            });
            for (let i = fires.length - 1; i >= 0; i--) {
                fires[i].update();
                fires[i].draw();
                if (fires[i].radius <= 0) {
                    fires.splice(i, 1);
                }
            }
        }
    };
    p.draw = function () {
        p.background(0);
        const bgTranslate = p.createVector(-background.distance, background.distance);
        const bgTranslate2 = bgTranslate.copy().add(0, -bgCanvas.height);
        const bgTranslate3 = bgTranslate.copy().add(bgCanvas.width, -bgCanvas.height);
        const bgTranslate4 = bgTranslate.copy().add(bgCanvas.width, 0);
        p.image(bgCanvas, Math.round(bgTranslate.x), Math.round(bgTranslate.y));
        p.image(bgCanvas, Math.round(bgTranslate2.x), Math.round(bgTranslate2.y));
        p.image(bgCanvas, Math.round(bgTranslate3.x), Math.round(bgTranslate3.y));
        p.image(bgCanvas, Math.round(bgTranslate4.x), Math.round(bgTranslate4.y));
        // draw framerate on screen
        p.fill(255);
        // fps.push(p.frameRate())
        // if (fps.length > 60) fps.shift()
        // const averageFps = fps.reduce((a, b) => a + b, 0) / fps.length
        // p.text(`FPS: ${averageFps.toFixed(2)}`, 10, 20)
        background.update();
        for (let i = fires.length - 1; i >= 0; i--) {
            fires[i].update();
            fires[i].draw();
            if (fires[i].radius <= 0) {
                fires.splice(i, 1);
            }
        }
        const fireRadius = rocket.exhausts === 1
            ? rocket._exhaustWidth * 2
            : rocket.exhausts === 2
                ? rocket._exhaustWidth * 2.5
                : rocket._exhaustWidth * 3;
        rocket._exhaustPoints.forEach(({ x, y }) => {
            fires.push(new Fire({
                pos: p
                    .createVector(x, y + rocket._exhaustWidth / 2)
                    .rotate(rocket.rotation)
                    .add(rocket.pos),
                radius: fireRadius,
                rotation: rocket.rotation,
                speed: features.speed * scale,
                colorPalette: firePalette,
            }, p));
        });
        rocket.draw();
    };
    p.windowResized = function () {
        p.resizeCanvas(p.windowWidth, p.windowHeight);
        scale = Math.min(p.width, p.height) / 1000;
        if (rocket)
            rocket.pos = p.createVector(p.width / 2, p.height / 2);
    };
};
new P5(sketch, document.body);
